        return !l.getGameRules().getBoolean(net.minecraft.world.level.GameRules.RULE_MOBGRIEFING)&&!l.getGameRules().getBoolean(net.minecraft.world.level.GameRules.RULE_NATURAL_REGENERATION)&&l.getBlockState(new BlockPos(16,-46,5)).is(Blocks.GLASS);
