        if(!geometry(level,phase.equals("GUEST")||phase.equals("BOTH"),phase.equals("BOTH")||phase.equals("HOST"))||!LabBlindIsolation.unloadSourcesClean(level)||!level.getForcedChunks().isEmpty()||server.tickRateManager().isFrozen()||server.tickRateManager().isSprinting()||server.tickRateManager().isSteppingForward()){finish("GEOMETRY_SOURCE_OR_CLOCK_CHANGED");return;}
